-- Seguimiento por facultades de los indicadores de L3 (semestre 1, semestre 2 y descripción).
-- Ejecutar DESPUÉS de carga_L3_2026.sql, y solo si la tabla
-- formulacion_distribucion_facultad_144 ya tiene las columnas seguimiento_sem1, seguimiento_sem2 y seguimiento_descripcion.
SET NAMES utf8mb4;
SET @base = (SELECT MAX(id) FROM formulacion_144 WHERE nombre_borrador = 'Centro de Lenguas Extranjeras constituido' AND linea_estrategica = 'Impacto regional, nacional e internacional desde la extensión y proyección social' AND creado_por = 1) - 1;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 1.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Se brindó acompañamiento integral a la Facultad de Arquitectura en la formulación, estructuración y gestión del Diplomado en Diseño Bioclimático de Edificaciones en Clima Cálido 2026, apoyando la consolidación de la propuesta académica, la revisión de contenidos, la construcción del presupuesto, la definición del equipo docente y el trámite de aval institucional, contribuyendo al fortalecimiento de la oferta de educación continua de la Facultad.' WHERE formulacion_id = @base+2 AND facultad_id = 1;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 0.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Durante el periodo no se presentaron propuestas de programas de educación continua por parte de la Facultad de Bellas Artes, razón por la cual no se registró avance en este indicador. Para el siguiente periodo se fortalecerá el acompañamiento a la Facultad con el fin de promover la formulación de nuevas ofertas académicas.' WHERE formulacion_id = @base+2 AND facultad_id = 2;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 0.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Durante el periodo no se presentaron propuestas de programas de educación continua por parte de la Facultad de Ciencias Básicas, razón por la cual no se registró avance en este indicador. Se continuará fortaleciendo el trabajo articulado con la Facultad para promover el diseño y desarrollo de nuevas ofertas de formación continua.' WHERE formulacion_id = @base+2 AND facultad_id = 3;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 12.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Durante el periodo se acompañó a la Facultad de Ciencias Económicas en la formulación, estructuración y gestión de seis programas de educación continua: el Diplomado en Procesamiento y Análisis de Datos Contables 2026-1, el Diplomado de Gerencia y Administración Tributaria, el Diplomado en Ciencia de Datos: Programación en Python y R, el Diplomado en Tributación y Política Fiscal, el Diplomado en Sistema de Administración de Riesgos de Lavado de Activos y Financiación del Terrorismo (SARLAFT) y Revisoría Fiscal, y el Seminario de Formación Profesional: Declaración de Renta para Persona Natural AG 2026. El Departamento de Extensión brindó acompañamiento técnico y administrativo en la estructuración académica, revisión presupuestal, trámite de avales y gestión institucional, fortaleciendo la oferta de educación continua de la Facultad y respondiendo a las necesidades de actualización profesional del sector.' WHERE formulacion_id = @base+2 AND facultad_id = 5;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 4.00, seguimiento_sem2 = NULL, seguimiento_descripcion = '1 exámen de inglés pregrado, 1 exámen de suficiencia b1 est de postgrados, 2 cohortes de minor' WHERE formulacion_id = @base+2 AND facultad_id = 6;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 6.00, seguimiento_sem2 = NULL, seguimiento_descripcion = '1-SEMINARIO ESPECIALIZDO DE PROFUNDIZACIÓN EN DERECHO CIVIL I\n2-SEMINARIO ESPECIALIZDO DE PROFUNDIZACIÓN EN DERECHO CIVIL II\n3-SEMINARIO ESPECIALIZDO DE PROFUNDIZACIÓN EN DERECHO PENAL\n4-SEMINARIO ESPECIALIZDO DE PROFUNDIZACIÓN EN DERECHO LABORAL\n5-SEMINARIO ESPECIALIZDO DE PROFUNDIZACIÓN EN DERECHO POLITÍCO\n6-DIPLOMADO SOBRE NUEVAS TENDENCIAS DE DERECHO LABORAL Y SEGURIDAD SOCIAL' WHERE formulacion_id = @base+2 AND facultad_id = 7;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 14.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Durante el periodo se brindó acompañamiento integral a la Facultad de Ciencias de la Educación en la formulación, estructuración y gestión de catorce (14) programas de educación continua, orientados al fortalecimiento de las competencias docentes y la innovación pedagógica. La oferta incluyó diplomados en Docencia Universitaria, Neuropedagogía y Educación Infantil, Abordaje Pedagógico de los Trastornos y Dificultades de Aprendizaje, Didáctica de las Ciencias Naturales y Nuevas Tecnologías, Fortalecimiento de la Formación Docente en Procesos de Lectura y Escritura Académica mediante la Pedagogía de Géneros Textuales, Enfoques Contemporáneos de la Educación Matemática y Emprendimiento desde la Educación Física, Recreación y Deportes. El Departamento de Extensión y Proyección Social brindó acompañamiento técnico y administrativo en la estructuración académica, revisión presupuestal, trámite de avales y gestión institucional, consolidando una oferta pertinente y de alta demanda para el sector educativo.' WHERE formulacion_id = @base+2 AND facultad_id = 4;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 2.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Durante el periodo se brindó acompañamiento a la Facultad de Ingeniería en la formulación, estructuración y gestión de dos (2) programas de educación continua: el Diplomado en Gestión de la Seguridad y Salud en el Trabajo – Cohorte XII y el programa de Formación Avanzada en Inspección, Ensayos Destructivos y No Destructivos Aplicados a Materiales, Componentes Industriales y Uniones Soldadas. El Departamento de Extensión y Proyección Social apoyó la consolidación de las propuestas académicas, la revisión de los componentes técnicos y financieros, el trámite de avales institucionales y la gestión administrativa requerida para su oferta, fortaleciendo la actualización profesional en áreas estratégicas para el desarrollo industrial y la ingeniería.' WHERE formulacion_id = @base+2 AND facultad_id = 8;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 1.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Se ha ofertado el Diplomado de de Sistema de Gestión de la la Calidad e Inocuidad Alimenatria, actualemtne en proceso de matricula para iniciar la priemra semana de julio' WHERE formulacion_id = @base+2 AND facultad_id = 9;
