UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 1.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Se brindó acompañamiento a la Facultad de Arquitectura en la formulación, estructuración y gestión del Diplomado en Diseño Bioclimático de Edificaciones en Clima Cálido 2026, programa desarrollado con componente internacional mediante la incorporación de contenidos y enfoques académicos de alcance global, orientados a las tendencias actuales de la arquitectura sostenible y el diseño bioclimático. El Departamento de Extensión y Proyección Social apoyó la consolidación de la propuesta académica, el trámite de avales institucionales y la gestión administrativa requerida para su oferta, contribuyendo al fortalecimiento de la estrategia de internacionalización de la educación continua.' WHERE formulacion_id = @base+3 AND facultad_id = 1;
