UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 1.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Se brindó acompañamiento a la Facultad de Ingeniería en la formulación, estructuración y gestión del Diplomado en Gestión de la Seguridad y Salud en el Trabajo – Cohorte XII, programa desarrollado con componente internacional mediante la incorporación de contenidos, referentes técnicos y buenas prácticas de alcance global en materia de seguridad y salud en el trabajo. El Departamento de Extensión y Proyección Social apoyó la consolidación de la propuesta académica, el trámite de avales institucionales y la gestión administrativa necesaria para su oferta, fortaleciendo la estrategia de internacionalización de la educación continua y promoviendo la actualización profesional conforme a estándares internacionales.' WHERE formulacion_id = @base+3 AND facultad_id = 8;
