UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 22.00, seguimiento_sem2 = NULL, seguimiento_descripcion = '1. Impacto tributario y económico del Decreto 1390 del 22 de diciembre de 2025 y su suspensión provisional por parte de la Corte Constitucional.\n2. Conversatorio virtual sobre dinámicas globales y su impacto en las empresas colombianas.\n3. UAE – Junta Central de Contadores, 70 años construyendo confianza: reflexión sobre el ejercicio de la contaduría pública en las regiones.\n4. IV Jornadas Institucionales del Contador(a) Público(a) - Universidad del Atlántico.\n5. Generación ODS Caribe: Investigaciones de jóvenes estudiantes de economía.\n6. Seminario profesional Especializado de información exógena.\n7. Conferencia Virtual Internacional Turismo Sostenible: De la Planificación a la Implementación Global.\n8. MOVILIDAD ENTRANTE: “Línea de Mercados Financieros"\n9. Aplicación de los Sistemas Integrados de Gestión WEBINAR.\n10. V FERIA UNIVERSITARIA TURÍSTICA FUTUR 2026 Rediseñando El Turismo Con Educación Ambiental E Inteligencia Artificial.\n11. I Encuentro Formativos de Semilleros del Programa de Contaduría Pública de la Universidad del Atlántico.\n12. Conversatorio: “Educación y Economía Conductual en la Era de la Inteligencia Artificial.”\n13. DANE en la academia: ¡ven y conoce el poder de los datos estadísticos!\n14. La paradoja del conflicto armado en Colombia: beneficios no esperados en la producción agrícola.\n15. Conéctate con la investigación: Seminario de Economía aplicada a tu proyecto académico.\n16. Conéctate con la investigación: Seminario de Economía aplicada a tu proyecto académico.\n17. Generalidades de Protección de datos personales.\n18. Centralidad urbana y desajuste espacial entre población y actividad económica: Caso Cartagena.\n19. Taller teórico práctico de Nómina.\n20. IV Escuela de Tecnología & Innovación formativa FCE \n21. II ENCUENTRO DEL SEMINARIO DE INVESTIGACIÓN ADMINISTRATIVA PRESENTACIÓN PRODUCTOS SEMINARIO DE INVESTIGACIÓN ADMINISTRATIVA\n22. 3er Encuentro Modelo Naciones Unidas ‘TURISMO SOSTENIBLE, RESILIENCIA TERRITORIAL Y DESARROLLO INCLUSIVO EN AMÉRICA LATINA Y EL CARIBE HACIA 2035' WHERE formulacion_id = @base+25 AND facultad_id = 5;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 14.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Se acompañó a la Facultad  en la formulación y ejecución de sus eventos de apropiación social del conocimiento, tales como talleres, capacitaciones, ferias, conferencias, paneles, semilleros, exposiciones y congresos.' WHERE formulacion_id = @base+25 AND facultad_id = 6;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 4.00, seguimiento_sem2 = NULL, seguimiento_descripcion = '1- Jornada Internacional de Derecho Público.\n2- Conversatorio de la sanción a la transformación: Ley de utilidad pública y\n\nresocialización.\n3- ACTIVIDADES PEDAGOGICAS SUPERSERVICIOS\n4- Firma del Acuerdo de Intenciones entre la Estación de Investigación COIBA AIP y el Centro de Investigaciones Jurídicas de la Universidad del Atlántico.' WHERE formulacion_id = @base+25 AND facultad_id = 7;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 21.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Durante 2026-1, la facultad realizó un total de 21 eventos, distribuidos entre sus distintos programas de la siguiente manera: Licenciatura en Educación Artística (6 eventos: 3er Conversatorio de Educación Artística, Experiencias significativas en investigación universitaria I Versión, Semana Internacional de la Educación Artística, Foro de arte para la vida – semillero ACIP, Seminario de Educación Artística y EXPO ARTE UNIMAGDALENA - Movilidad Docente), Licenciatura en Matemáticas (6 eventos: Juramento de Estudiantes de Prácticas, Seminario de Formación “Las IA aplicadas a la Educación”, Socialización de Prácticas Profesionales, Claustro de estudiantes de práctica, Celebración del día del licenciado en matemáticas UA y Encuentro de Rectores y Coordinadores), Licenciatura en Educación Física, Recreación y Deportes (4 eventos: Segundo Congreso Internacional Carnaval, Educación y Transmisión de Saberes, Encuentro Académico Metodologías y Transmisión de Saberes UNICESAR, Olimpiadas Deporte Formativo 2026-1 y Torneo de tenis PRIME OPEN 2026), Licenciatura en Lenguas Extranjeras (2 eventos: Proyecciones del mes de la Francofonía y 3er Festival de Cine Francófono y la Jornada Interuniversitaria de Socialización de Experiencias Investigativas), Licenciatura en Ciencias Naturales (1 evento: Encuentro de Egresados de Licenciatura en Ciencias Naturales y Maestría en Educación), Licenciatura en Ciencias Sociales (1 evento: Semana de las Ciencias Sociales) y Licenciatura en Educación Especial (1 evento: XXI Encuentro de Instituciones en convenio).' WHERE formulacion_id = @base+25 AND facultad_id = 4;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 11.00, seguimiento_sem2 = NULL, seguimiento_descripcion = '1. Sé ANEIAP 2026-1\n2. IV JORNADA ACADÉMICA DE INGENIERÍA QUÍMICA (JAIQ)\n3. "XXXVI EDICION DEL ENCUENTRO NACIONAL DE ESTUDIANTES DE INGENIERIA QUIMICA Y CARRERAS AFINES - ENEIQ 2026"\n4. Simposio Internacional de Innovación Agroindustrial\n5. AGROEMPRENDE 2026\n6. CHARLA DE COPNIA\n7. CATEDRA MONOMEROS\n8. Capacitación Uso bases de datos disponibles de la Biblioteca Orlando Fals Borda de la Universidad del Atlántico\n9. 32° Asamblea General Ordinaria \n10. Panel “Hablemos sobre la planificación de las operaciones en plantas industriales”\n11. “VII Jornada Técnica de Prevención de Riesgos Laborales: Confort térmico, riesgos y controles”.' WHERE formulacion_id = @base+25 AND facultad_id = 8;
